from collections import deque
import sys,time
from genfast import GenFast as Base

class GenMerge(Base):
    def __init__(self,H,participants,roots,edge_mode='nat'):
        self.edge_mode=edge_mode
        super().__init__(H,participants,roots)
        # Rebuild initial active/queue with a pending structure map.
        self.pending={}
        # active already has initial keys; q deque initial
        q=deque()
        for key in list(self.active.keys()):
            st=self._struct(key)
            self.pending[st]=key
            q.append(key)
        self.q=q
    def _struct(self,key):
        return (self.roots_of[key], frozenset(self.Vs[key]), tuple(sorted(self.Ts[key])))
    def _ys(self,x):
        ys=list(self.Hadj[x].keys())
        if self.edge_mode=='cap_asc':ys.sort(key=lambda y:(self.Hadj[x].get(y,0),y))
        elif self.edge_mode=='cap_desc':ys.sort(key=lambda y:(-self.Hadj[x].get(y,0),y))
        elif self.edge_mode=='rev':ys.sort(reverse=True)
        else:ys.sort()
        return ys
    def _add_remainder(self,root,edges,nodes,C):
        st=(root,frozenset(nodes),tuple(sorted(edges)))
        old=self.pending.get(st)
        if old is not None:
            self.Cs[old]+=C
            return old,False
        key=self.new_tree(root,edges,nodes,C)  # new_tree appends to self.q; for now
        # new_tree uses self.q; ensure it is deque
        self.pending[st]=key
        return key,True
    def generate(self):
        while self.q:
            key=self.q.popleft()
            st=self._struct(key)
            if self.pending.get(st)==key:
                del self.pending[st]
            root=self.roots_of[key]
            bfs=deque(sorted(self.Vs[key]))
            while bfs:
                x=bfs.popleft()
                for y in self._ys(x):
                    if y in self.Vs[key]:continue
                    if self.Hadj[x].get(y,0)<=0:continue
                    chunks=self.test_edge(key,x,y)
                    if chunks<=0:continue
                    bfs.append(y)
                    if chunks<self.Cs[key]:
                        remC=self.Cs[key]-chunks
                        # old structure before adding this edge
                        self._add_remainder(root,self.Ts[key],self.Vs[key],remC)
                        self.Cs[key]=chunks
                    self.Ts[key].append((x,y));self.Vs[key].add(y)
                    c=self.Hadj[x][y]-chunks
                    if c==0:del self.Hadj[x][y]
                    else:self.Hadj[x][y]=c
            del self.active[key]
        sums={u:0 for u in self.roots}
        for key,C in self.Cs.items():sums[self.roots_of[key]]+=C
        for u,c in self.roots.items():
            if sums.get(u,0)!=c:raise Exception(('sum',u,sums.get(u,0),c))
        return self.Ts,self.Cs
